import { useCallback, useMemo, useState } from "react";

export function SalesPanel({ sales, region }: Props) {
  const [note, setNote] = useState("");
  const title = useMemo(() => `Sales: ${region}`, [region]);
  const points = useMemo(() => toPoints(sales), [sales]);
  const onSelect = useCallback((id: string) => openSale(region, id), [region]);

  // ChartView isn't wrapped in memo: stable props change nothing
  return (
    <>
      <textarea value={note} onChange={(e) => setNote(e.target.value)} />
      <ChartView
        title={title}
        points={points}
        options={{ animate: false }} // a new object on every render
        onSelect={onSelect}
      />
    </>
  );
}

import { memo, useCallback, useMemo, useState } from "react";

const Chart = memo(ChartView); // skips renders when every prop is equal
const options = { animate: false }; // static: created once

export function SalesPanel({ sales, region }: Props) {
  const [note, setNote] = useState("");
  const title = `Sales: ${region}`; // strings compare by value
  const points = useMemo(() => toPoints(sales), [sales]);
  const onSelect = useCallback((id: string) => openSale(region, id), [region]);

  return (
    <>
      <textarea value={note} onChange={(e) => setNote(e.target.value)} />
      <Chart title={title} points={points} options={options} onSelect={onSelect} />
    </>
  );
}
